import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        // Each distinct even value is halved once, all its copies together; process the largest first.
        HashSet<Long> seen = new HashSet<>();
        PriorityQueue<Long> evens = new PriorityQueue<>(Collections.reverseOrder());
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            if (seen.add(v) && v % 2 == 0) evens.add(v);
        }
        long ans = 0;
        while (!evens.isEmpty()) {
            long half = evens.poll() / 2;
            ans++;
            if (seen.add(half) && half % 2 == 0) evens.add(half);
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type maxHeap []int64

func (h maxHeap) Len() int           { return len(h) }
func (h maxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h maxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x any)        { *h = append(*h, x.(int64)) }
func (h *maxHeap) Pop() any {
	old := *h
	v := old[len(old)-1]
	*h = old[:len(old)-1]
	return v
}

